import { collapseTransitionProps, cardProps } from "naive-ui";
const proCardExtendProps = {
  /**
   * 提示文字，显示在 title 的右边
   */
  tooltip: {
    type: [String, Array]
  },
  /**
   * 触发展开的区域，如果不想让某些区域触发展开，可以使用此属性
   */
  triggerAreas: {
    type: Array,
    default: () => ["main", "arrow"]
  },
  /**
   * 是否显示展开收起
   */
  showCollapse: {
    type: Boolean,
    default: true
  }
};
const proCardProps = {
  ...cardProps,
  ...proCardExtendProps,
  ...collapseTransitionProps
};
export {
  proCardExtendProps,
  proCardProps
};
